		new("renaissance_military_kote_japanese", "Armour & barding", "c. 1550 Japanese sleeve armour", "kote", "a pair of Japanese kote", "These cloth sleeves carry small linked plates over the arms and backs of the hands. Dark cords lace the plates along each outer seam. Their soft inner faces tie snugly beneath the elbows.", SizeCategory.Normal, ItemQuality.VeryGood, 2380, 624m, true, "silk", ["Era / Renaissance Era", "Culture / Renaissance / Shared / Japanese", "Functions / Military Equipment", "Functions / Military Equipment / Military Armour", "Market / Military Goods", "Market / Military Goods / Armour", "Market / Military Goods / Armour / Plate Armour"], ["Holdable", "Wear_ArmHarness", "Armour_Lamellar", "Destroyable_Armour"], "Renaissance military catalogue; category Armour & barding; admission c. 1550 Japanese sleeve armour; component profile Holdable, Wear_ArmHarness, Armour_Lamellar, Destroyable_Armour."),
		new("renaissance_military_kusazuri_japanese", "Armour & barding", "c. 1550 Japanese skirt armour", "kusazuri", "a laced Japanese kusazuri", "This skirt defence hangs in several deep laced panels from the cuirass. Each panel is built from close rows of small lacquered plates. The lower cords swing freely beneath stiffened upper bands.", SizeCategory.Normal, ItemQuality.VeryGood, 2860, 682m, true, "wrought iron", ["Era / Renaissance Era", "Culture / Renaissance / Shared / Japanese", "Functions / Military Equipment", "Functions / Military Equipment / Military Armour", "Market / Military Goods", "Market / Military Goods / Armour", "Market / Military Goods / Armour / Plate Armour"], ["Holdable", "Wear_Tassets", "Armour_Lamellar", "Destroyable_Armour"], "Renaissance military catalogue; category Armour & barding; admission c. 1550 Japanese skirt armour; component profile Holdable, Wear_Tassets, Armour_Lamellar, Destroyable_Armour."),
		new("renaissance_military_suneate_japanese", "Armour & barding", "c. 1550 Japanese shin armour", "suneate", "a pair of Japanese suneate", "These iron shin guards are lined with dark cloth beneath narrow vertical plates. Their edges curve around the calves without covering the knees. Two cords tie the guards behind each leg.", SizeCategory.Normal, ItemQuality.Good, 2480, 548m, true, "wrought iron", ["Era / Renaissance Era", "Culture / Renaissance / Shared / Japanese", "Functions / Military Equipment", "Functions / Military Equipment / Military Armour", "Market / Military Goods", "Market / Military Goods / Armour", "Market / Military Goods / Armour / Plate Armour"], ["Holdable", "Wear_Greaves", "Armour_Lamellar", "Destroyable_Armour"], "Renaissance military catalogue; category Armour & barding; admission c. 1550 Japanese shin armour; component profile Holdable, Wear_Greaves, Armour_Lamellar, Destroyable_Armour."),
		new("renaissance_military_menpo_japanese", "Armour & barding", "c. 1550 Japanese face and throat defence", "menpo", "a Japanese menpo mask", "This dark lacquered mask covers the cheeks and chin beneath a narrow nose opening. A curved throat plate hangs from its lower edge on small cords. Its inner face is padded around the jaw.", SizeCategory.Small, ItemQuality.Good, 1180, 368m, true, "wrought iron", ["Era / Renaissance Era", "Culture / Renaissance / Shared / Japanese", "Functions / Military Equipment", "Functions / Military Equipment / Military Armour", "Market / Military Goods", "Market / Military Goods / Armour", "Market / Military Goods / Armour / Plate Armour"], ["Holdable", "Wear_Bevor", "Armour_RigidMetal", "Destroyable_Armour"], "Renaissance military catalogue; category Armour & barding; admission c. 1550 Japanese face and throat defence; component profile Holdable, Wear_Bevor, Armour_RigidMetal, Destroyable_Armour."),
		new("renaissance_military_mail_shirt_tatar", "Armour & barding", "c. 1500 Tatar cavalry mail", "shirt", "a Tatar mail shirt", "This light iron mail shirt is cut high at the sides for riding. Its sleeves end neatly above the wrists beneath leather binding. The close rings lie flat around a short open collar.", SizeCategory.Normal, ItemQuality.Good, 6840, 1120m, true, "wrought iron", ["Era / Renaissance Era", "Culture / Renaissance / Shared / Steppe and Caravan", "Functions / Military Equipment", "Functions / Military Equipment / Military Armour", "Market / Military Goods", "Market / Military Goods / Armour", "Market / Military Goods / Armour / Mail Armour"], ["Holdable", "Wear_Haubergeon", "Armour_Chainmail", "Destroyable_Armour"], "Renaissance military catalogue; category Armour & barding; admission c. 1500 Tatar cavalry mail; component profile Holdable, Wear_Haubergeon, Armour_Chainmail, Destroyable_Armour."),
		new("renaissance_military_helmet_tatar_conical", "Armour & barding", "c. 1500 Tatar cavalry helmet", "helmet", "a conical Tatar helmet", "This iron helmet rises to a narrow point over a rounded bowl. A small nasal plate hangs below its simple brow. Linked mail descends from the rear rim over the neck.", SizeCategory.Small, ItemQuality.Good, 1880, 436m, true, "wrought iron", ["Era / Renaissance Era", "Culture / Renaissance / Shared / Steppe and Caravan", "Functions / Military Equipment", "Functions / Military Equipment / Military Armour", "Market / Military Goods", "Market / Military Goods / Armour", "Market / Military Goods / Armour / Plate Armour"], ["Holdable", "Wear_Helmet", "Armour_RigidMetal", "Destroyable_Armour"], "Renaissance military catalogue; category Armour & barding; admission c. 1500 Tatar cavalry helmet; component profile Holdable, Wear_Helmet, Armour_RigidMetal, Destroyable_Armour."),
