		new("renaissance_military_helmet_uzbek_lamellar", "Armour & barding", "c. 1500 Uzbek cavalry helmet", "helmet", "an Uzbek lamellar helmet", "This rounded helmet is faced with small laced iron plates over a leather cap. A narrow brim shades the brow above a mail curtain. Its top knot is wrapped in dark cord.", SizeCategory.Small, ItemQuality.Good, 2020, 474m, true, "wrought iron", ["Era / Renaissance Era", "Culture / Renaissance / Shared / Steppe and Caravan", "Functions / Military Equipment", "Functions / Military Equipment / Military Armour", "Market / Military Goods", "Market / Military Goods / Armour", "Market / Military Goods / Armour / Plate Armour"], ["Holdable", "Wear_Helmet", "Armour_Lamellar", "Destroyable_Armour"], "Renaissance military catalogue; category Armour & barding; admission c. 1500 Uzbek cavalry helmet; component profile Holdable, Wear_Helmet, Armour_Lamellar, Destroyable_Armour."),
		new("renaissance_military_rattan_vest_siamese", "Armour & barding", "c. 1550 Siamese infantry protection", "vest", "a woven Siamese rattan vest", "This sleeveless rattan vest is tightly woven in broad flat bands. Its pale surface is bound in dark rawhide around the neck and arms. Two cords tie the stiff panels together at the sides.", SizeCategory.Normal, ItemQuality.Standard, 3260, 238m, true, "rattan", ["Era / Renaissance Era", "Culture / Renaissance / Shared / South-east Asian Mainland", "Functions / Military Equipment", "Functions / Military Equipment / Military Armour", "Market / Military Goods", "Market / Military Goods / Armour", "Market / Military Goods / Armour / Primitive Armour"], ["Holdable", "Wear_Vest", "Armour_Rattan", "Destroyable_Armour"], "Renaissance military catalogue; category Armour & barding; admission c. 1550 Siamese infantry protection; component profile Holdable, Wear_Vest, Armour_Rattan, Destroyable_Armour."),
		new("renaissance_military_cuirass_burmese_rattan", "Armour & barding", "c. 1550 Burmese guard armour", "cuirass", "a Burmese rattan cuirass", "This rounded cuirass is woven from thick rattan strips over a leather frame. Its front closes along one side with broad cloth ties. Rawhide binding follows the rim and the short shoulder straps.", SizeCategory.Normal, ItemQuality.Good, 4180, 362m, true, "rattan", ["Era / Renaissance Era", "Culture / Renaissance / Shared / South-east Asian Mainland", "Functions / Military Equipment", "Functions / Military Equipment / Military Armour", "Market / Military Goods", "Market / Military Goods / Armour", "Market / Military Goods / Armour / Primitive Armour"], ["Holdable", "Wear_Cuirass", "Armour_Rattan", "Destroyable_Armour"], "Renaissance military catalogue; category Armour & barding; admission c. 1550 Burmese guard armour; component profile Holdable, Wear_Cuirass, Armour_Rattan, Destroyable_Armour."),
