		new("renaissance_military_jack_sahelian_quilted", "Armour & barding", "c. 1550 Sahelian cavalry quilted armour", "jack", "a quilted Sahelian jack", "This long cotton jack is densely quilted through its chest and sleeves. Its skirt is split at the sides for riding. Dark leather binding reinforces the high collar and cuff edges.", SizeCategory.Normal, ItemQuality.Good, 4680, 392m, true, "cotton", ["Era / Renaissance Era", "Culture / Renaissance / Shared / Sahelian Islamic", "Functions / Military Equipment", "Functions / Military Equipment / Military Armour", "Market / Military Goods", "Market / Military Goods / Armour"], ["Holdable", "Wear_Jacket", "Armour_Padded", "Destroyable_Armour"], "Renaissance military catalogue; category Armour & barding; admission c. 1550 Sahelian cavalry quilted armour; component profile Holdable, Wear_Jacket, Armour_Padded, Destroyable_Armour."),
		new("renaissance_military_mail_shirt_ethiopian", "Armour & barding", "c. 1550 Ethiopian highland mail", "shirt", "an Ethiopian mail shirt", "This iron mail shirt falls to the hips in close riveted rings. Its short sleeves sit beneath a simple leather collar. The lower hem is split slightly at both sides for walking.", SizeCategory.Normal, ItemQuality.Good, 7280, 1220m, true, "wrought iron", ["Era / Renaissance Era", "Culture / Renaissance / Shared / Red Sea", "Functions / Military Equipment", "Functions / Military Equipment / Military Armour", "Market / Military Goods", "Market / Military Goods / Armour", "Market / Military Goods / Armour / Mail Armour"], ["Holdable", "Wear_Haubergeon", "Armour_Chainmail", "Destroyable_Armour"], "Renaissance military catalogue; category Armour & barding; admission c. 1550 Ethiopian highland mail; component profile Holdable, Wear_Haubergeon, Armour_Chainmail, Destroyable_Armour."),
